import { Component, EventEmitter, Input, Output, output } from '@angular/core';
import { LeafletComponent } from '../../leaflet/leaflet.component';
import { FormGroupComponent, GroupStyle } from "../form-group/form-group.component";

export interface MapField{
  title:string;
  key?:string;
  latitud:{
    key:string;
    value?:number;
  },
  longitud:{
    key:string;
    value?:number;
  }
  style?: GroupStyle;
  valid?:boolean;
}

@Component({
    selector: 'app-map-field',
    imports: [
        LeafletComponent,
        FormGroupComponent
    ],
    templateUrl: './map-field.component.html',
    styleUrl: './map-field.component.css'
})
export class MapFieldComponent {
  @Input() title!:string
  @Input() style?: GroupStyle;
  @Input() latitud?:number
  @Output() latitudChange= new EventEmitter<number>()
  @Input() longitud?:number
  @Output() longitudChange = new EventEmitter<number>()
  @Input() valid?:boolean
  @Output() validChange = new EventEmitter<boolean>()

  ngOnInit(){
    this.valid=true
    this.validChange.emit(true)
  }
}
